import{_ as o,o as t,c as a,a2 as i}from"./chunks/framework.dMg474VA.js";const p=JSON.parse('{"title":"Architecture Decision Records (ADRs)","description":"","frontmatter":{},"headers":[],"relativePath":"decisions.md","filePath":"decisions.md"}'),n={name:"decisions.md"};function r(c,e,s,l,d,h){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="architecture-decision-records-adrs" tabindex="-1">Architecture Decision Records (ADRs) <a class="header-anchor" href="#architecture-decision-records-adrs" aria-label="Permalink to &quot;Architecture Decision Records (ADRs)&quot;">​</a></h1><h2 id="adr-001-hand-rolled-streaming-reverse-proxy-vs-http-proxy" tabindex="-1">ADR-001: Hand-Rolled Streaming Reverse Proxy vs <code>http-proxy</code> <a class="header-anchor" href="#adr-001-hand-rolled-streaming-reverse-proxy-vs-http-proxy" aria-label="Permalink to &quot;ADR-001: Hand-Rolled Streaming Reverse Proxy vs `http-proxy`&quot;">​</a></h2><h3 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h3><p>RLGW serves as a high-throughput, low-latency API gateway enforcing distributed rate limits before proxying requests upstream.</p><h3 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h3><p>We implement a hand-rolled streaming reverse proxy directly on Node.js <code>node:http.request</code> and <code>node:https.request</code> with pooled, keep-alive <code>Agent</code> instances instead of adopting external libraries such as <code>http-proxy</code> or <code>express-http-proxy</code>.</p><h3 id="justification" tabindex="-1">Justification <a class="header-anchor" href="#justification" aria-label="Permalink to &quot;Justification&quot;">​</a></h3><ol><li><strong>Zero-Buffering Streaming</strong>: <code>stream.pipeline</code> guarantees backpressure-aware byte-for-byte forwarding without buffering request or response payloads in memory.</li><li><strong>Explicit Hop-by-Hop Stripping</strong>: RFC 7230 requires stripping <code>Connection</code>, <code>Keep-Alive</code>, <code>Proxy-Authenticate</code>, <code>Proxy-Authorization</code>, <code>TE</code>, <code>Trailer</code>, <code>Transfer-Encoding</code>, and <code>Upgrade</code>, plus any token listed in the incoming <code>Connection</code> header. Hand-rolled logic guarantees exact compliance.</li><li><strong>Deterministic Timeout &amp; Abort Handling</strong>: Full control over connect timeouts, response header timeouts, and client disconnects (<code>req.on(&#39;aborted&#39;)</code>) avoids socket and timer leaks.</li><li><strong>WebSocket &amp; Protocol Upgrade</strong>: Direct control over the <code>upgrade</code> event enables seamless bidirectional piping.</li></ol><hr><h2 id="adr-002-injectable-monotonic-clock-vs-global-wall-clock" tabindex="-1">ADR-002: Injectable Monotonic Clock vs Global Wall-Clock <a class="header-anchor" href="#adr-002-injectable-monotonic-clock-vs-global-wall-clock" aria-label="Permalink to &quot;ADR-002: Injectable Monotonic Clock vs Global Wall-Clock&quot;">​</a></h2><h3 id="context-1" tabindex="-1">Context <a class="header-anchor" href="#context-1" aria-label="Permalink to &quot;Context&quot;">​</a></h3><p>Rate-limiting algorithms depend on time deltas for token refill and window alignment. Relying on <code>Date.now()</code> causes defects during NTP step adjustments and prevents deterministic testing.</p><h3 id="decision-1" tabindex="-1">Decision <a class="header-anchor" href="#decision-1" aria-label="Permalink to &quot;Decision&quot;">​</a></h3><p>All algorithms and components accept an injectable <code>Clock</code> (<code>SystemClock</code>, <code>FakeClock</code>, <code>SkewedClock</code>). Direct calls to <code>Date.now()</code> are restricted exclusively to <code>packages/core/src/clock.ts</code>.</p><hr><h2 id="adr-003-two-phase-decide-semantics-for-multi-policy-evaluation" tabindex="-1">ADR-003: Two-Phase Decide Semantics for Multi-Policy Evaluation <a class="header-anchor" href="#adr-003-two-phase-decide-semantics-for-multi-policy-evaluation" aria-label="Permalink to &quot;ADR-003: Two-Phase Decide Semantics for Multi-Policy Evaluation&quot;">​</a></h2><h3 id="context-2" tabindex="-1">Context <a class="header-anchor" href="#context-2" aria-label="Permalink to &quot;Context&quot;">​</a></h3><p>When requests match multiple policies (e.g. global IP throttle + route limit + tenant tier), committing intermediate counters before all checks complete leaks quota if a later policy rejects.</p><h3 id="decision-2" tabindex="-1">Decision <a class="header-anchor" href="#decision-2" aria-label="Permalink to &quot;Decision&quot;">​</a></h3><p>RLGW executes an atomic two-phase check:</p><ol><li><strong>Phase 1 (Peek)</strong>: All matching policies are evaluated non-mutatively via <code>peek</code>. If any rejects, zero counters are touched.</li><li><strong>Phase 2 (Commit)</strong>: If all allow, counters are committed sequentially.</li><li><strong>Rollback</strong>: If a concurrent race condition causes a commit to fail, all earlier committed policies in the chain are refunded immediately via <code>refund</code>.</li></ol><hr><h2 id="adr-004-redis-cluster-hash-tags-tenant-subject-for-counter-co-location" tabindex="-1">ADR-004: Redis Cluster Hash-Tags <code>{tenant:subject}</code> for Counter Co-Location <a class="header-anchor" href="#adr-004-redis-cluster-hash-tags-tenant-subject-for-counter-co-location" aria-label="Permalink to &quot;ADR-004: Redis Cluster Hash-Tags `{tenant:subject}` for Counter Co-Location&quot;">​</a></h2><h3 id="context-3" tabindex="-1">Context <a class="header-anchor" href="#context-3" aria-label="Permalink to &quot;Context&quot;">​</a></h3><p>In Redis Cluster, multi-key operations and multi-policy transactional scripts require that all involved keys hash to the identical 16,384 cluster slot.</p><h3 id="decision-3" tabindex="-1">Decision <a class="header-anchor" href="#decision-3" aria-label="Permalink to &quot;Decision&quot;">​</a></h3><p><code>KeyBuilder</code> generates all Redis counter keys with the hash-tag pattern <code>rl:{tenant:subject}:scope:policyId</code>.</p><h3 id="consequence" tabindex="-1">Consequence <a class="header-anchor" href="#consequence" aria-label="Permalink to &quot;Consequence&quot;">​</a></h3><p>All keys for the same tenant and subject (e.g. client ID or IP) co-locate in the exact same Redis node, enabling zero-cross-slot-error multi-policy evaluation and transactional atomic execution.</p><hr><h2 id="adr-005-hot-key-shielding-micro-batching-with-local-degrade-fallback" tabindex="-1">ADR-005: Hot-Key Shielding &amp; Micro-Batching with Local Degrade Fallback <a class="header-anchor" href="#adr-005-hot-key-shielding-micro-batching-with-local-degrade-fallback" aria-label="Permalink to &quot;ADR-005: Hot-Key Shielding &amp; Micro-Batching with Local Degrade Fallback&quot;">​</a></h2><h3 id="context-4" tabindex="-1">Context <a class="header-anchor" href="#context-4" aria-label="Permalink to &quot;Context&quot;">​</a></h3><p>High-frequency hot keys generate severe lock contention and connection saturation on Redis master nodes. In the event of network partition or Redis failure, service availability must be preserved.</p><h3 id="decision-4" tabindex="-1">Decision <a class="header-anchor" href="#decision-4" aria-label="Permalink to &quot;Decision&quot;">​</a></h3><ol><li><strong>Hot-Key Shielding</strong>: <code>HotKeyShield</code> uses a Space-Saving Top-K heavy hitters sketch to detect hot keys and grant bounded local token leases, avoiding remote round-trips for the duration of the lease.</li><li><strong>Micro-Batching</strong>: <code>PipelineBatcher</code> groups concurrent <code>peek</code> inspections into Redis pipelines within a bounded linger window (≤ 2 ms).</li><li><strong>Degrade-Local Fallback</strong>: When Redis connectivity is interrupted, <code>RedisLimiterStore</code> automatically switches to <code>degraded_local</code> mode using <code>MemoryLimiterStore</code> to prevent cascading gateway timeouts.</li></ol>',35)])])}const m=o(n,[["render",r]]);export{p as __pageData,m as default};
